# satterthwaite_parity.R — per-draw Satterthwaite df and decisions, MCPower vs
# lmerTest, on the SAME generated bytes, for linear mixed models with a random
# slope (tested at Satterthwaite df under df_method = "auto").
#
# Each draw: MCPowerDebug$create_data() generates one dataset at the design's
# N; MCPowerDebug$load_data() fits it through MCPower's data -> results path
# (per-target df, statistic, critical value); lmerTest::lmer refits the
# identical design matrix, outcome and cluster ids (REML, unstructured random
# effects as lmer fits them) and reports its Satterthwaite df and p-values.
# Draws are classified by MCPower's fit: not converged; converged with no
# component pinned; partly pinned (a diagonal entry of the random-effect
# Cholesky factor at zero: a variance at zero, or a singular random-effect
# correlation matrix such as a correlation at +-1, which lme4's isSingular()
# also counts); fully pinned (every
# random-effect variance at zero). A converged MCPower fit reported as a Wald z
# (no df) is a failed Satterthwaite pass.
#
# Designs: Example 2 of the MCPower paper, y ~ group * time + (1 + time | subject),
# 8 rows per subject, group cluster-level and binary, ICC .3, slope variance .10,
# group:time = 0, at 10, 20, 30 and 60 subjects; and a two-slope design,
# y ~ x1 + x2 + (1 + x1 + x2 | g), 20 clusters of 10, all effects 0.
#
# Usage (from mcpower/validation/):
#   Rscript satterthwaite_parity.R [draws_per_design] [workers] [draws_csv]
# Writes data/satterthwaite_parity_summary.csv (one row per design, target and
# fit class) and prints it. The per-draw table (one row per draw and target,
# about 12 MB at 4,000 draws) goes outside the repository: to draws_csv, else
# $SATT_PARITY_DRAWS, else satterthwaite_parity_draws.csv in the user cache
# directory (tools::R_user_dir("mcpower", "cache")).
suppressMessages({ library(mcpower); library(parallel) })
script_dir <- local({
  fa <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
  if (length(fa)) dirname(normalizePath(sub("^--file=", "", fa[1]))) else getwd()
})
setwd(script_dir)

args    <- commandArgs(trailingOnly = TRUE)
DRAWS   <- if (length(args) >= 1) as.integer(args[1]) else 500L
WORKERS <- if (length(args) >= 2) as.integer(args[2]) else 4L
DRAWS_CSV <- if (length(args) >= 3) args[3] else Sys.getenv(
  "SATT_PARITY_DRAWS",
  file.path(tools::R_user_dir("mcpower", "cache"), "satterthwaite_parity_draws.csv"))
ALPHA   <- 0.05
SEED0   <- 20261030

DESIGNS <- c(
  lapply(c(10L, 20L, 30L, 60L), function(J) list(
    label = sprintf("ex2_J%d", J), J = J, m = 8L,
    formula = "y ~ group * time + (1 + time|subject)",
    types = "group=binary", effects = "group=0.3, time=0.4, group:time=0",
    cluster = "subject", icc = 0.3, cluster_level = "group",
    slopes = list(list(predictor = "time", variance = 0.10)),
    # design columns: intercept, group, time, group:time; slope on time
    labels = c("group", "time", "group:time"), slope_cols = 3L)),
  list(list(
    label = "two_slope_J20", J = 20L, m = 10L,
    formula = "y ~ x1 + x2 + (1 + x1 + x2|g)",
    types = NULL, effects = "x1=0, x2=0",
    cluster = "g", icc = 0.2, cluster_level = NULL,
    slopes = list(list(predictor = "x1", variance = 0.10),
                  list(predictor = "x2", variance = 0.10, corr_with = 0)),
    labels = c("x1", "x2"), slope_cols = c(2L, 3L)))
)

build <- function(des) {
  m <- MCPowerDebug$new(des$formula, family = "lme",
                        debug_n = des$J * des$m, debug_n_sims = 1L)
  if (!is.null(des$types)) m$set_variable_type(des$types)
  m$set_effects(des$effects)
  args <- list(des$cluster, ICC = des$icc, n_clusters = des$J,
               random_slopes = des$slopes)
  if (!is.null(des$cluster_level)) args$cluster_level_vars <- des$cluster_level
  do.call(m$set_cluster, args)
  m
}

# One draw: both fits on the same bytes, one row per target.
one_draw <- function(des, m, draw) {
  m$.debug_seed <- SEED0 + 1000L * des$J + draw
  d   <- m$create_data()
  fit <- m$load_data(d)
  vc  <- unlist(fit$variance_components)
  rc  <- unlist(fit$re_corr)
  n_slope <- length(des$slope_cols)
  diag_vc <- vc[seq_len(1L + n_slope)]
  # Random-effect correlation matrix from re_corr (vech, column-major lower
  # triangle); a zero eigenvalue is a pinned diagonal Cholesky entry.
  q <- 1L + n_slope
  R <- diag(q)
  if (length(rc) == q * (q - 1L) / 2L) {
    R[lower.tri(R)] <- rc
    R[upper.tri(R)] <- t(R)[upper.tri(R)]
  }
  corr_eig_min <- min(eigen(R, symmetric = TRUE, only.values = TRUE)$values)
  cls <- if (!isTRUE(fit$converged)) "not_converged"
         else if (all(diag_vc == 0)) "fully_pinned"
         else if (any(diag_vc == 0) || corr_eig_min < 1e-6) "partly_pinned"
         else "converged"

  X  <- d$design
  p  <- ncol(X)
  vn <- paste0("V", seq_len(p))
  df <- as.data.frame(X); names(df) <- vn
  df$.y <- d$outcome; df$.g <- factor(d$cluster_ids)
  re  <- paste(c("1", vn[des$slope_cols]), collapse = " + ")
  fml <- stats::as.formula(paste(".y ~ 0 +", paste(vn, collapse = " + "), "+ (", re, "| .g)"))
  muffle <- function(w) invokeRestart("muffleWarning")
  lt <- tryCatch(withCallingHandlers(
    lmerTest::lmer(fml, data = df, REML = TRUE), warning = muffle,
    message = function(c) invokeRestart("muffleMessage")), error = function(e) NULL)
  sm <- if (is.null(lt)) NULL else tryCatch(withCallingHandlers(
    summary(lt, ddf = "Satterthwaite")$coefficients, warning = muffle),
    error = function(e) NULL)
  # A rank-deficient draw (lmer drops an aliased column, e.g. a binary
  # cluster-level predictor equal in every cluster) has no row per column;
  # it counts as an lmerTest failure.
  if (!is.null(sm) && nrow(sm) != p) sm <- NULL
  lt_sing <- if (is.null(lt)) NA else lme4::isSingular(lt)

  rows <- lapply(fit$targets, function(tg) {
    j <- tg$target_index + 1L
    mc_kind <- tg$statistic_kind
    mc_df   <- if (length(tg$df)) tg$df[[1]] else NA_real_
    stat    <- abs(tg$statistic)
    mc_p    <- if (identical(mc_kind, "t")) 2 * stats::pt(-stat, mc_df) else 2 * stats::pnorm(-stat)
    lt_df   <- if (!is.null(sm) && "df" %in% colnames(sm)) sm[j, "df"] else NA_real_
    lt_t    <- if (!is.null(sm)) abs(sm[j, "t value"]) else NA_real_
    lt_p    <- if (!is.null(sm) && "Pr(>|t|)" %in% colnames(sm)) sm[j, "Pr(>|t|)"] else NA_real_
    data.frame(design = des$label, J = des$J, draw = draw,
               target = des$labels[j - 1L], fit_class = cls,
               mc_converged = isTRUE(fit$converged), mc_kind = mc_kind,
               mc_vc_min = if (length(diag_vc)) min(diag_vc) else NA_real_,
               mc_corr_eig_min = corr_eig_min,
               mc_df = mc_df, mc_t = stat, mc_p = mc_p,
               mc_sig = isTRUE(fit$converged) && stat > tg$critical_value,
               lt_ok = !is.null(sm), lt_singular = lt_sing,
               lt_df = lt_df, lt_t = lt_t, lt_p = lt_p,
               lt_sig = !is.na(lt_p) && lt_p <= ALPHA,
               stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

# A draw that errors is kept out of the table and reported by message.
run_chunk <- function(task) {
  suppressMessages(library(mcpower))
  des  <- task$des
  m    <- build(des)
  errs <- character(0)
  rows <- lapply(task$draws, function(k) tryCatch(one_draw(des, m, k), error = function(e) {
    errs <<- c(errs, sprintf("%s draw %d: %s", des$label, k, conditionMessage(e)))
    NULL
  }))
  list(rows = do.call(rbind, rows), errs = errs)
}

tasks <- unlist(lapply(DESIGNS, function(des) {
  chunks <- split(seq_len(DRAWS), cut(seq_len(DRAWS), WORKERS, labels = FALSE))
  lapply(chunks, function(dr) list(des = des, draws = dr))
}), recursive = FALSE)

t0 <- Sys.time()
cl <- parallel::makePSOCKcluster(WORKERS)
invisible(parallel::clusterEvalQ(cl, Sys.setenv(RAYON_NUM_THREADS = "1", OMP_NUM_THREADS = "1")))
parallel::clusterExport(cl, c("build", "one_draw", "ALPHA", "SEED0"))
res <- parallel::parLapplyLB(cl, tasks, run_chunk)
parallel::stopCluster(cl)
draws <- do.call(rbind, lapply(res, `[[`, "rows"))
errs  <- unlist(lapply(res, `[[`, "errs"))
elapsed <- as.numeric(difftime(Sys.time(), t0, units = "mins"))

dir.create("data", showWarnings = FALSE)
dir.create(dirname(DRAWS_CSV), recursive = TRUE, showWarnings = FALSE)
utils::write.csv(draws, DRAWS_CSV, row.names = FALSE)

# Summary per design, target and fit class (plus an "all" class).
summ_one <- function(x) {
  both <- x$mc_converged & x$lt_ok & x$mc_kind == "t" & is.finite(x$lt_df)
  rel  <- abs(x$mc_df[both] - x$lt_df[both]) / x$lt_df[both]
  q    <- function(v, p) if (length(v)) unname(stats::quantile(v, p)) else NA_real_
  data.frame(
    n_draws        = nrow(x),
    mc_failed_df   = sum(x$mc_converged & x$mc_kind != "t"),
    lt_failed      = sum(!x$lt_ok | !is.finite(x$lt_df)),
    n_compared     = sum(both),
    df_mc_median   = q(x$mc_df[both], 0.5),
    df_lt_median   = q(x$lt_df[both], 0.5),
    df_rel_median  = q(rel, 0.5),
    df_rel_p95     = q(rel, 0.95),
    df_rel_max     = if (length(rel)) max(rel) else NA_real_,
    t_rel_max      = if (any(both)) max(abs(x$mc_t[both] - x$lt_t[both]) / x$lt_t[both]) else NA_real_,
    decisions_differ = sum(x$mc_sig[both] != x$lt_sig[both]),
    mc_reject      = mean(x$mc_sig),
    lt_reject      = mean(x$lt_sig),
    lt_singular    = mean(x$lt_singular, na.rm = TRUE))
}
keys <- unique(draws[, c("design", "target")])
summary_rows <- list()
for (i in seq_len(nrow(keys))) {
  sub <- draws[draws$design == keys$design[i] & draws$target == keys$target[i], ]
  for (cls in c("all", "converged", "partly_pinned", "fully_pinned", "not_converged")) {
    x <- if (cls == "all") sub else sub[sub$fit_class == cls, ]
    if (!nrow(x)) next
    summary_rows[[length(summary_rows) + 1L]] <-
      cbind(data.frame(design = keys$design[i], target = keys$target[i], fit_class = cls),
            summ_one(x))
  }
}
summary <- do.call(rbind, summary_rows)
utils::write.csv(summary, file.path("data", "satterthwaite_parity_summary.csv"), row.names = FALSE)
options(width = 200)
print(summary, digits = 3, row.names = FALSE)
if (length(errs)) {
  cat(sprintf("\n%d draws errored and are left out:\n", length(errs)))
  cat(paste0("  ", utils::head(errs, 20)), sep = "\n")
}
cat(sprintf("\nper-draw table: %s\n", DRAWS_CSV))
cat(sprintf("\n%d draws per design, %d workers, %.1f min; mcpower %s, lmerTest %s, lme4 %s\n",
            DRAWS, WORKERS, elapsed, utils::packageVersion("mcpower"),
            utils::packageVersion("lmerTest"), utils::packageVersion("lme4")))
